class Mailbox {
	private final Deque<String> items = new ArrayDeque<>();

	synchronized void put(String s) {
		items.addLast(s);
		notifyAll();
	}

	synchronized String take() throws InterruptedException {
		if (items.isEmpty()) {
			wait();
		}
		return items.removeFirst();
	}
}

